using Bogus;
using Xunit;

public class User
{
    public int Id { get; set; }
    public string FirstName { get; set; }
    public string LastName { get; set; }
    public string Email { get; set; }
}

[Fact]
public void Generate_Fake_Users()
{
    var userFaker = new Faker<User>()
        .RuleFor(u => u.Id, f => f.UniqueIndex)
        .RuleFor(u => u.FirstName, f => f.Name.FirstName())
        .RuleFor(u => u.LastName, f => f.Name.LastName())
        .RuleFor(u => u.Email, (f, u) => f.Internet.Email(u.FirstName, u.LastName));

    var user = userFaker.Generate();

    Assert.False(string.IsNullOrEmpty(user.FirstName));
    Assert.Contains("@", user.Email);
}

[Fact]
public void Seed_Test_Database_With_Fake_Users()
{
    var userFaker = new Faker<User>()
        .RuleFor(u => u.Id, f => f.UniqueIndex)
        .RuleFor(u => u.FirstName, f => f.Name.FirstName())
        .RuleFor(u => u.LastName, f => f.Name.LastName())
        .RuleFor(u => u.Email, (f, u) => f.Internet.Email(u.FirstName, u.LastName));

    var users = userFaker.Generate(10);

    Assert.Equal(10, users.Count);
    Assert.All(users, u => Assert.NotNull(u.Email));
}
